# --- ① Thread 를 상속한다 ---

$ cat ExtendThread.java
public class ExtendThread extends Thread {
    ExtendThread(String name) { super(name); }

    @Override public void run() {
        log.info("일한다");
    }

    public static void main(String[] args) {
        log.info("만들기 전");
        new ExtendThread("w-0").start();
        new ExtendThread("w-1").start();
        log.info("만든 뒤");
    }
}

$ java -cp out:libs/* ExtendThread
00:03:02.104 [main        ] INFO  ExtendThread - 만들기 전
00:03:02.108 [main        ] INFO  ExtendThread - 만든 뒤
00:03:02.108 [w-0         ] INFO  ExtendThread - 일한다
00:03:02.108 [w-1         ] INFO  ExtendThread - 일한다

#   "만든 뒤" 가 먼저 찍혔다
#   start() 가 안 기다린다


# --- ② Runnable 을 넘긴다 ---

$ cat PassRunnable.java
public class PassRunnable {
    static class Work implements Runnable {
        @Override public void run() { log.info("일한다"); }
    }

    public static void main(String[] args) {
        Runnable work = new Work();
        new Thread(work, "w-0").start();
        new Thread(work, "w-1").start();       // 같은 객체를 둘이 쓴다
    }
}

$ java -cp out:libs/* PassRunnable
00:03:06.204 [w-0         ] INFO  PassRunnable - 일한다
00:03:06.204 [w-1         ] INFO  PassRunnable - 일한다

$ ./run.sh PassRunnable 10 '일한다' | head -2
  20 일한다

#   같은 Runnable 객체를 둘이 나눠 썼다
#   2.2절에서 본 그 공유다


# --- 상속 자리를 써 버린다 ---

$ cat CannotExtend.java
class Base { void help() {} }

class Worker extends Thread, Base { }     // 안 된다

$ javac -d out CannotExtend.java 2>&1 | head -2
CannotExtend.java:3: error: '{' expected
class Worker extends Thread, Base { }
                           ^

$ cat CanImplement.java
class Worker extends Base implements Runnable {
    @Override public void run() { help(); }
}

$ javac -d out CanImplement.java && echo '컴파일 됨'
컴파일 됨

