# --- 무엇이 생겼나 ---

$ cat WhatExists.java | grep -A6 'main'
public static void main(String[] args) throws Exception {
    Thread t = new Thread(() -> sleep(3000), "w-0");
    log.info("start 전 상태 {}", t.getState());
    t.start();
    log.info("start 후 상태 {}", t.getState());
    Thread.sleep(200);
    log.info("조금 뒤 상태 {}", t.getState());
}

