# --- start 전에는 OS 스레드가 없다 ---

$ cat CountBefore.java | grep -A5 'main'
public static void main(String[] args) throws Exception {
    log.info("만들기 전 {}", Thread.activeCount());
    Thread[] ts = new Thread[100];
    for (int i = 0; i < 100; i++) ts[i] = new Thread(() -> sleep(3000));
    log.info("객체만 만든 뒤 {}", Thread.activeCount());
    for (Thread t : ts) t.start();
    log.info("start 한 뒤 {}", Thread.activeCount());
}

