# --- 같은 Runnable 을 여럿이 쓰면 ---

$ cat SharedRunnable.java
static class Counting implements Runnable {
    int count = 0;                          // 인스턴스 필드다
    @Override public void run() {
        for (int i = 0; i < 100000; i++) count++;
    }
}

public static void main(String[] args) throws Exception {
    Counting shared = new Counting();
    Thread[] ts = new Thread[4];
    for (int i = 0; i < 4; i++) { ts[i] = new Thread(shared, "w-" + i); ts[i].start(); }
    for (Thread t : ts) t.join();
    log.info("기대 400000 실제 {}", shared.count);
}

$ ./run.sh SharedRunnable 20 '[0-9]+$' | head -3
   2 400000
   1 312041
   1 298412

$ ./run.sh SharedRunnable 20 '[0-9]+$' | awk '$2==400000 {print "맞음", $1"/20"}'
맞음 2/20

